dcStepExt:
int dcStepExt(int n, int fromExt, int dir, dcChanAt_t at, void *ctx)
{
 int total = n + 2;
 int e = fromExt;
 if ((n < 0) || ((dir != 1) && (dir != -1)))
 {
  return -1;
 }
 if ((e < 0) || (e >= total))
 {
  e = ((dir > 0) ? -1 : total);
 }
 for (int i = 0; i < total; i++)
 {
  e += dir;
  if (e < 0)
  {
   e = total - 1;
  }
  else if (e >= total)
  {
   e = 0;
  }
  if ((e >= n) || (at(e, ctx) != 0U))
  {
   return e;
  }
 }
 return -1;
}

dualStepB:
static void dualStepB(int dir)
{
 CodeplugZone_t zb;
 const CodeplugZone_t *z = dualZoneB(&zb);
 const CodeplugZone_t *zz = ((z != ((void *)0)) ? z : &currentZone);
 void *ctx = (void *)z;
 int n = (((*zz).NOT_IN_CODEPLUGDATA_indexNumber < 0) ? zz->NOT_IN_CODEPLUGDATA_highestIndex : zz->NOT_IN_CODEPLUGDATA_numChannelsInZone);
 int from;
 if (dcBIsVfo())
 {
  from = (n + (int)dualVfoIdx());
 }
 else
 {
  from = dcFindPos(n, dcChannelB(), dualZoneChannelAt, ctx);
  if ((from < 0) && (z == ((void *)0)))
  {
   from = dcFindPos(n, dualChannelA(), dualZoneChannelAt, ((void *)0));
  }
 }
 int pos = dcStepExt(n, from, dir, dualZoneChannelAt, ctx);
 if (pos < 0)
 {
  soundSetMelody(MELODY_ERROR_BEEP);
  return;
 }
 dualBReset();
 if (pos >= n)
 {
  dcSetTypeB((pos == n) ? 1U : 2U);
 }
 else
 {
  (void)dcSetChannelB(dualZoneChannelAt(pos, ctx), 0);
 }
 if (dualIsRunning() == 0)
 {
  s_dualKeyMs = 0U;
  dualAutoResume();
 }
 else if (dcIsOnB())
 {
  uiDataGlobal.Scan.state = SCAN_STATE_SCANNING;
  dualTune(1);
  dualSetDwell();
 }
}

