  uint16_t ch = dualZoneChannelAt(pos, ((void *)0));
  if (dcIsOnB())
  {
   dualTune(0);
  }
  if (dcAIsVfo())
  {
   s_dualBKeep = 0U;
  }
  dcSetTypeA(0U);
  codeplugSetLastUsedChannelInZone(currentZone.NOT_IN_CODEPLUGDATA_indexNumber, (int16_t)(((currentZone).NOT_IN_CODEPLUGDATA_indexNumber < 0) ? (int)ch : pos));
  currentChannelData = &channelScreenChannelData;
