{
 return (dcIsEnabled() && dualCardIsVfo(dcPointerB()) && (menuSystemGetCurrentMenuNumber() == UI_CHANNEL_MODE) &&
   (((ev)->buttons & 0x00000020)) && ((((ev)->buttons & 0x00000002)) == 0) &&
   ((ev->keys.key == 8) || (ev->keys.key == 7)));
}

dualHandleKey:
static _Bool dualHandleKey(uiEvent_t *ev)
{
 if (dualIsVfoStepKey(ev))
 {
  if (((ev->keys.key == ev->keys.key) && ((ev->keys.event & (0x02 | 0x04)) == 0x02)))
  {
   dualSuspend();
   if (dcIsOnB() != dcPointerB())
   {
    dualTune(dcPointerB());
   }
   if (dualOnVfoNow())
   {
    uiVFOModeDualStep(dualCardVfo(dcIsOnB()), ((ev->keys.key == 8) ? 1 : -1));
   }
   uiDataGlobal.displayQSOState = QSO_DISPLAY_DEFAULT_SCREEN;
   uiChannelModeUpdateScreen(0);
  }
  return 1;
 }
 if (dualIsSquelchKey(ev))
 {
  if (((ev->keys.key == ev->keys.key) && ((ev->keys.event & (0x02 | 0x04)) == 0x02)))
  {
   dualSquelchStep((ev->keys.key == 8) ? 1 : -1);
  }
  return 1;
 }
 if ((((ev)->buttons & 0x00000020)) && ((((ev)->buttons & 0x00000002)) == 0) &&
   ((ev->keys.key == 8) || (ev->keys.key == 7)))
 {
  if (((ev->keys.key == ev->keys.key) && ((ev->keys.event & (0x02 | 0x04)) == 0x02)))
  {
   int dir = ((ev->keys.key == 8) ? 1 : -1);
   if (dcPointerB() && (dualSingle() == 0))
   {
    dualZoneStepB(dir);
    uiDataGlobal.displayQSOState = QSO_DISPLAY_DEFAULT_SCREEN;
    uiChannelModeUpdateScreen(0);
   }
   else
   {
    dualSuspend();
    if (dcIsOnB())
    {
     dualTune(0);
    }
    s_dualQuiet = 1;
    if (dir > 0)
    {
     handleUpKey(ev);
    }
    else
    {
     handleDownKey(ev);
    }
   }
  }
  return 1;
 }
 if ((((ev)->buttons & 0x00000020)) || (((ev)->buttons & 0x00000002)))
 {
  return 0;
 }
 switch (ev->keys.key)
 {
  case 9:
  case 10:
   if ((ev->keys.key == 10) && ((ev->keys.key == 10) && ((ev->keys.event & (0x01 | 0x04)) == (0x01 | 0x04))) && (((ev->keys.key == 10) && ((ev->keys.event & (0x08 | 0x04)) == (0x08 | 0x04))) == 0))
   {
    dualHotkeyToggle();
    return 1;
   }
   if (((ev->keys.key == ev->keys.key) && ((ev->keys.event & (0x02 | 0x04)) == 0x02)))
   {
    dcSetPointerB(ev->keys.key == 10);
    uiDataGlobal.displayQSOState = QSO_DISPLAY_DEFAULT_SCREEN;
    uiChannelModeUpdateScreen(0);
   }
   return 1;
  case 8:
  case 7:
   if (((ev->keys.key == ev->keys.key) && ((ev->keys.event & (0x02 | 0x04)) == 0x02)))
   {
    int dir = ((ev->keys.key == 8) ? 1 : -1);
    if (dcPointerB())
    {
     dualStepB(dir);
    }
    else if (dualStepA(dir))
    {
     return 1;
    }
    else
    {
     dualSuspend();
     if (dcIsOnB())
     {
      dualTune(0);
     }
     s_dualQuiet = 1;
     if (dir > 0)
     {
      handleUpKey(ev);
     }
     else
     {
      handleDownKey(ev);
     }
     s_dualQuiet = 0;
     s_dualKeyMs = 0U;
     dualAutoResume();
     if (dualIsRunning() == 0)
     {
      uiChannelModeUpdateScreen(0);
     }
     return 1;
    }
    uiDataGlobal.displayQSOState = QSO_DISPLAY_DEFAULT_SCREEN;
    uiChannelModeUpdateScreen(0);
   }
   return 1;
  case 27:
   return 1;
  default:
   break;
 }
 return 0;
}
